/**
 * A task event from the Google cluster-usage trace (task_events table).
 *
 * <p>Schema fields (CSV, comma-separated):
 * <ol>
 *   <li>timestamp (microseconds)</li>
 *   <li>missing info</li>
 *   <li>job ID</li>
 *   <li>task index</li>
 *   <li>machine ID</li>
 *   <li>event type (0=SUBMIT, 1=SCHEDULE, 2=EVICT, 3=FAIL, 4=FINISH,
 *       5=KILL, 6=LOST, 7=UPDATE_PENDING, 8=UPDATE_RUNNING)</li>
 *   <li>user name</li>
 *   <li>scheduling class</li>
 *   <li>priority</li>
 *   <li>CPU request</li>
 *   <li>memory request</li>
 *   <li>disk space request</li>
 *   <li>different-machine constraint</li>
 * </ol>
 */
public class TaskEvent {

    public static final int SUBMIT = 0;
    public static final int SCHEDULE = 1;
    public static final int EVICT = 2;
    public static final int FAIL = 3;
    public static final int FINISH = 4;
    public static final int KILL = 5;
    public static final int LOST = 6;

    public long timestamp;
    public long jobId;
    public long taskIndex;
    public int eventType;

    public TaskEvent() {}

    public TaskEvent(long timestamp, long jobId, long taskIndex, int eventType) {
        this.timestamp = timestamp;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.eventType = eventType;
    }

    public static TaskEvent fromCsv(String line) {
        String[] f = line.split(",", -1);
        TaskEvent e = new TaskEvent();
        e.timestamp = Long.parseLong(f[0]);
        e.jobId = Long.parseLong(f[2]);
        e.taskIndex = f[3].isEmpty() ? -1L : Long.parseLong(f[3]);
        e.eventType = Integer.parseInt(f[5]);
        return e;
    }

    public long getTimestamp() { return timestamp; }
    public long getJobId() { return jobId; }
    public long getTaskIndex() { return taskIndex; }
    public int getEventType() { return eventType; }

    @Override
    public String toString() {
        return "TaskEvent{ts=" + timestamp + ", job=" + jobId
                + ", task=" + taskIndex + ", event=" + eventType + "}";
    }
}
