        DataStream<Tuple2<Long, Integer>> sessionCounts = submits
                .keyBy((KeySelector<TaskEvent, Long>) te -> te.jobId)
                .window(EventTimeSessionWindows.withGap(Time.milliseconds(gapMs)))
                .aggregate(new CountAgg(), new EmitSessionCount());

        // Join session counts with job-finish signals, emit max per finished job.
        DataStream<Tuple2<Long, Integer>> result = sessionCounts
                .keyBy((KeySelector<Tuple2<Long, Integer>, Long>) t -> t.f0)
                .connect(jobFinishes.keyBy((KeySelector<JobEvent, Long>) je -> je.jobId))
                .process(new MaxSessionFinalizer(gapMs));

